    "NOT LINKED" to Tr(ja = "リンク なし", fr = "NON LIÉ", de = "NICHT VERKNÜPFT", it = "NON COLLEGATA", es = "SIN VINCULAR", br = "NÃO VINCULADA", pt = "NÃO VINCULADA", ko = "연결 안 됨"),
    "Link the folder you keep your games in: its supported ROMs join the library and play from there." to Tr(ja = "ゲームを いれている フォルダを リンクすると、 たいおう ROMが ライブラリに くわわり、 そこから あそべます。", fr = "Liez le dossier où vous gardez vos jeux : ses ROM compatibles rejoignent la bibliothèque et se lancent depuis là.", de = "Verknüpfe den Ordner mit deinen Spielen: Seine unterstützten ROMs kommen in die Bibliothek und laufen direkt von dort.", it = "Collega la cartella in cui tieni i giochi: le sue ROM supportate entrano nella libreria e si avviano da lì.", es = "Vincula la carpeta donde guardas tus juegos: sus ROMs compatibles se suman a la biblioteca y se juegan desde ahí.", br = "Vincule a pasta onde você guarda seus jogos: as ROMs suportadas dela entram na biblioteca e rodam de lá.", pt = "Vincule a pasta onde guarda os seus jogos: as ROMs suportadas entram na biblioteca e são jogadas a partir de lá.", ko = "게임을 보관하는 폴더를 연결하세요. 지원하는 ROM이 라이브러리에 추가되고 그 자리에서 실행돼요."),
    "LOOKING FOR GAMES…" to Tr(ja = "ゲームを さがしています…", fr = "RECHERCHE DE JEUX…", de = "SUCHE SPIELE…", it = "CERCO GIOCHI…", es = "BUSCANDO JUEGOS…", br = "PROCURANDO JOGOS…", pt = "A PROCURAR JOGOS…", ko = "게임 찾는 중…"),
    "{0} GAME(S) IN THE LIBRARY · CHECKED FOR NEW ONES EACH TIME THE APP OPENS" to Tr(ja = "ライブラリに ゲーム {0}こ · アプリを ひらく たびに あたらしい ゲームを さがします", fr = "{0} JEU(X) DANS LA BIBLIOTHÈQUE · NOUVEAUX JEUX CHERCHÉS À CHAQUE OUVERTURE", de = "{0} SPIEL(E) IN DER BIBLIOTHEK · BEI JEDEM APP-START AUF NEUE GEPRÜFT", it = "{0} GIOCHI NELLA LIBRERIA · NUOVI CERCATI A OGNI AVVIO DELL'APP", es = "{0} JUEGO(S) EN LA BIBLIOTECA · SE BUSCAN NUEVOS CADA VEZ QUE SE ABRE LA APP", br = "{0} JOGO(S) NA BIBLIOTECA · NOVOS SÃO BUSCADOS SEMPRE QUE O APP ABRE", pt = "{0} JOGO(S) NA BIBLIOTECA · NOVOS PROCURADOS SEMPRE QUE A APP ABRE", ko = "라이브러리에 게임 {0}개 · 앱을 열 때마다 새 게임 확인"),
