    "Grant \"All files access\", then tap the button again" to Tr(ja = "「すべての ファイルへの アクセス」を きょかしてから もういちど ボタンを タップしてください", fr = "Accordez « Accès à tous les fichiers », puis touchez à nouveau le bouton", de = "Erlaube „Zugriff auf alle Dateien“ und tippe dann erneut auf die Schaltfläche", it = "Concedi «Accesso a tutti i file», poi tocca di nuovo il pulsante", es = "Concede «Acceso a todos los archivos» y vuelve a tocar el botón", br = "Conceda \"Acesso a todos os arquivos\" e toque no botão de novo", pt = "Conceda \"Acesso a todos os ficheiros\" e toque novamente no botão", ko = "\"모든 파일 액세스\" 권한을 허용한 뒤 버튼을 다시 탭하세요"),
