    "NO CHEATS FOR THIS GAME" to Tr(ja = "この ゲームの チートは ありません", fr = "AUCUNE TRICHE POUR CE JEU", de = "KEINE CHEATS FÜR DIESES SPIEL", it = "NESSUN TRUCCO PER QUESTO GIOCO", es = "NINGÚN TRUCO PARA ESTE JUEGO", br = "NENHUMA TRAPAÇA PARA ESTE JOGO", pt = "NENHUMA BATOTA PARA ESTE JOGO", ko = "이 게임의 치트 없음"),
    "ADD THEM IN SETTINGS ON THE TOP SCREEN" to Tr(ja = "うえの がめんの せっていで ついか", fr = "À AJOUTER DANS LES OPTIONS DE L'ÉCRAN DU HAUT", de = "IN DEN OPTIONEN OBEN HINZUFÜGEN", it = "AGGIUNGILI NELLE OPZIONI DELLO SCHERMO IN ALTO", es = "AÑÁDELOS EN AJUSTES EN LA PANTALLA DE ARRIBA", br = "ADICIONE-AS NAS CONFIG. DA TELA DE CIMA", pt = "ADICIONE-AS NAS DEFINIÇÕES DO ECRÃ DE CIMA", ko = "위 화면의 설정에서 추가하세요"),
    "NO GAMES IN THE LIBRARY" to Tr(ja = "ライブラリに ゲームが ありません", fr = "AUCUN JEU DANS LA BIBLIOTHÈQUE", de = "KEINE SPIELE IN DER BIBLIOTHEK", it = "NESSUN GIOCO IN LIBRERIA", es = "NINGÚN JUEGO EN LA BIBLIOTECA", br = "NENHUM JOGO NA BIBLIOTECA", pt = "NENHUM JOGO NA BIBLIOTECA", ko = "라이브러리에 게임 없음"),
    "A cheat can break a save, so the save is backed up every time a game starts (RESTORE BACKUP in its library menu). Achievements pause while a cheat is on." to Tr(ja = "チートで セーブが こわれる ことも あるので ゲームを はじめる たびに セーブの バックアップを とります (ライブラリの メニューの バックアップを もどす)。 チートが オンの あいだ じっせきは とまります。", fr = "Une triche peut abîmer une sauvegarde : elle est copiée à chaque lancement (RESTAURER COPIE dans le menu du jeu). Les succès sont en pause tant qu'une triche est active.", de = "Ein Cheat kann einen Spielstand beschädigen: Er wird bei jedem Start gesichert (BACKUP LADEN im Menü des Spiels). Erfolge pausieren, solange ein Cheat an ist.", it = "Un trucco può rovinare un salvataggio: viene copiato a ogni avvio (RIPRISTINA BACKUP nel menu del gioco). Gli obiettivi sono in pausa finché un trucco è attivo.", es = "Un truco puede estropear una partida: se copia cada vez que empieza un juego (RESTAURAR COPIA en su menú). Los logros se pausan mientras haya un truco activo.", br = "Uma trapaça pode estragar um save, então é feito um backup dele toda vez que um jogo começa (RESTAURAR BACKUP no menu dele na biblioteca). As conquistas pausam enquanto uma trapaça estiver ativa.", pt = "Uma batota pode estragar um jogo guardado, por isso é feita uma cópia sempre que um jogo começa (RESTAURAR CÓPIA no seu menu da biblioteca). As conquistas ficam em pausa enquanto uma batota estiver ativa.", ko = "치트는 세이브를 망가뜨릴 수 있어서, 게임을 시작할 때마다 세이브를 백업해요(라이브러리 메뉴의 백업 복원). 치트가 켜져 있는 동안 업적은 일시 정지돼요."),
    "Type or paste a GameShark, Action Replay or CodeBreaker code, one line or many. AUTO works out which it is; pick the type when a code doesn't take." to Tr(ja = "ゲームシャーク アクションリプレイ コードブレイカーの コードを いれてください (なんぎょうでも)。 オートで しゅるいを みわけます。 うまく いかない ときは しゅるいを えらんでください。", fr = "Tapez ou collez un code GameShark, Action Replay ou CodeBreaker, sur une ou plusieurs lignes. AUTO trouve lequel c'est ; choisissez le type si un code ne passe pas.", de = "Tippe oder füge einen GameShark-, Action-Replay- oder CodeBreaker-Code ein, eine Zeile oder mehrere. AUTO erkennt die Art; wähle den Typ, wenn ein Code nicht klappt.", it = "Scrivi o incolla un codice GameShark, Action Replay o CodeBreaker, su una o più righe. AUTO capisce quale è; scegli il tipo se un codice non funziona.", es = "Escribe o pega un código GameShark, Action Replay o CodeBreaker, en una línea o varias. AUTO averigua cuál es; elige el tipo si un código no funciona.", br = "Digite ou cole um código GameShark, Action Replay ou CodeBreaker, em uma ou várias linhas. AUTO descobre qual é; escolha o tipo se um código não funcionar.", pt = "Escreva ou cole um código GameShark, Action Replay ou CodeBreaker, numa ou várias linhas. AUTO descobre qual é; escolha o tipo se um código não funcionar.", ko = "GameShark, Action Replay, CodeBreaker 코드를 입력하거나 붙여 넣으세요. 한 줄도 여러 줄도 돼요. 자동이 종류를 알아내요. 코드가 안 먹히면 종류를 직접 고르세요."),
    "e.g. INFINITE MONEY" to Tr(ja = "れい: おかね むげん", fr = "ex. ARGENT INFINI", de = "z. B. UNENDLICH GELD", it = "es. SOLDI INFINITI", es = "p. ej. DINERO INFINITO", br = "ex. DINHEIRO INFINITO", pt = "ex. DINHEIRO INFINITO", ko = "예: 돈 무한"),
    "Type or paste an Action Replay DS code, one line or many." to Tr(ja = "アクションリプレイDSの コードを いれてください (なんぎょうでも)。", fr = "Tapez ou collez un code Action Replay DS, sur une ou plusieurs lignes.", de = "Tippe oder füge einen Action-Replay-DS-Code ein, eine Zeile oder mehrere.", it = "Scrivi o incolla un codice Action Replay DS, su una o più righe.", es = "Escribe o pega un código Action Replay DS, en una línea o varias.", br = "Digite ou cole um código Action Replay DS, em uma ou várias linhas.", pt = "Escreva ou cole um código Action Replay DS, numa ou várias linhas.", ko = "Action Replay DS 코드를 입력하거나 붙여 넣으세요. 한 줄도 여러 줄도 돼요."),
    "{0} isn't an Action Replay DS line." to Tr(ja = "{0} は アクションリプレイDSの ぎょうでは ありません。", fr = "{0} n'est pas une ligne Action Replay DS.", de = "{0} ist keine Action-Replay-DS-Zeile.", it = "{0} non è una riga Action Replay DS.", es = "{0} no es una línea de Action Replay DS.", br = "{0} não é uma linha de Action Replay DS.", pt = "{0} não é uma linha de Action Replay DS.", ko = "Action Replay DS 코드 줄이 아니에요: {0}"),
    "That isn't a code." to Tr(ja = "コードでは ありません。", fr = "Ce n'est pas un code.", de = "Das ist kein Code.", it = "Questo non è un codice.", es = "Eso no es un código.", br = "Isso não é um código.", pt = "Isso não é um código.", ko = "코드가 아니에요."),
