    "That file has no cheats in a format PokeDaisy reads (RetroArch .cht, mGBA .cheats)." to Tr(ja = "この ファイルには よめる チートが ありません (RetroArchの .cht mGBAの .cheats)。", fr = "Ce fichier n'a aucune triche dans un format lu par PokeDaisy (.cht de RetroArch, .cheats de mGBA).", de = "Die Datei hat keine Cheats in einem Format, das PokeDaisy liest (RetroArch .cht, mGBA .cheats).", it = "Il file non ha trucchi in un formato che PokeDaisy legge (.cht di RetroArch, .cheats di mGBA).", es = "El archivo no tiene trucos en un formato que PokeDaisy lea (.cht de RetroArch, .cheats de mGBA).", br = "Esse arquivo não tem trapaças em um formato que o PokeDaisy lê (.cht do RetroArch, .cheats do mGBA).", pt = "Esse ficheiro não tem batotas num formato que o PokeDaisy leia (.cht do RetroArch, .cheats do mGBA).", ko = "이 파일에는 PokeDaisy가 읽는 형식(RetroArch .cht, mGBA .cheats)의 치트가 없어요."),
    "{0} CHEATS ADDED" to Tr(ja = "チートを {0}こ ついか", fr = "{0} TRICHES AJOUTÉES", de = "{0} CHEATS HINZUGEFÜGT", it = "{0} TRUCCHI AGGIUNTI", es = "{0} TRUCOS AÑADIDOS", br = "{0} TRAPAÇAS ADICIONADAS", pt = "{0} BATOTAS ADICIONADAS", ko = "치트 {0}개 추가됨"),
    "They start OFF: tap one to turn it on." to Tr(ja = "さいしょは オフです。 タッチで オンに なります。", fr = "Elles sont désactivées : touchez-en une pour l'activer.", de = "Sie sind aus: tippe einen an, um ihn einzuschalten.", it = "Partono spenti: tocca un trucco per attivarlo.", es = "Empiezan desactivados: toca uno para activarlo.", br = "Começam DESLIGADAS: toque em uma para ativá-la.", pt = "Começam DESLIGADAS: toque numa para a ativar.", ko = "처음에는 꺼져 있어요. 탭하면 켜져요."),
    "{0} left out: mGBA can't read {1} of their code lines." to Tr(ja = "{0}こは はずしました: {1}ぎょうの コードが よめません。", fr = "{0} ignorées : mGBA ne peut pas lire {1} de leurs lignes de code.", de = "{0} ausgelassen: mGBA kann {1} ihrer Codezeilen nicht lesen.", it = "{0} esclusi: mGBA non riesce a leggere {1} delle loro righe di codice.", es = "{0} omitidos: mGBA no puede leer {1} de sus líneas de código.", br = "{0} deixadas de fora: o mGBA não consegue ler {1} das linhas de código delas.", pt = "{0} deixadas de fora: o mGBA não consegue ler {1} das suas linhas de código.", ko = "{0}개 제외: mGBA가 코드 줄 {1}개를 읽을 수 없어요."),
