    "A frame around the game. {0} and {1} are PokéDaisy's own. {2} adds yours: a RetroArch overlay (.cfg with its PNG), a .zip of them, or a PNG with a see-through screen." to Tr(ja = "ゲームの まわりの わくです。 {0}と {1}は PokéDaisyの ものです。 {2}で じぶんの ものを ふやせます: RetroArchの オーバーレイ (.cfgと その PNG)、 それの .zip、 または がめんが すけている PNG。", fr = "Un cadre autour du jeu. {0} et {1} sont ceux de PokéDaisy. {2} ajoute les vôtres : une surimpression RetroArch (.cfg avec son PNG), un .zip de celles-ci, ou un PNG avec un écran transparent.", de = "Ein Rahmen um das Spiel. {0} und {1} gehören zu PokéDaisy. {2} fügt eigene hinzu: ein RetroArch-Overlay (.cfg mit seinem PNG), ein .zip davon oder ein PNG mit durchsichtigem Bildschirm.", it = "Una cornice intorno al gioco. {0} e {1} sono di PokéDaisy. {2} aggiunge le tue: un overlay di RetroArch (.cfg con il suo PNG), uno .zip di overlay o un PNG con lo schermo trasparente.", es = "Un marco alrededor del juego. {0} y {1} son de PokéDaisy. {2} añade los tuyos: una superposición de RetroArch (.cfg con su PNG), un .zip de ellas o un PNG con la pantalla transparente.", br = "Uma moldura em volta do jogo. {0} e {1} são do PokéDaisy. {2} adiciona as suas: uma moldura do RetroArch (.cfg com o PNG dela), um .zip delas ou um PNG com a tela transparente.", pt = "Uma moldura em volta do jogo. {0} e {1} são do PokéDaisy. {2} adiciona as suas: uma moldura do RetroArch (.cfg com o seu PNG), um .zip delas ou um PNG com o ecrã transparente.", ko = "게임을 두르는 프레임이에요. PokéDaisy 기본 프레임: {0}, {1}. {2} 버튼으로 직접 추가할 수 있어요: RetroArch 오버레이(.cfg와 PNG), 그 .zip 파일, 또는 화면 부분이 투명한 PNG."),
    "OVERLAY ADDED" to Tr(ja = "オーバーレイを ついかしました", fr = "SURIMPRESSION AJOUTÉE", de = "OVERLAY HINZUGEFÜGT", it = "OVERLAY AGGIUNTO", es = "SUPERPOSICIÓN AÑADIDA", br = "MOLDURA ADICIONADA", pt = "MOLDURA ADICIONADA", ko = "오버레이 추가됨"),
