    "{0} is on. Games show it from now on." to Tr(ja = "{0}を つかいます。 これから ゲームに でます。", fr = "{0} est activée. Les jeux l'affichent désormais.", de = "{0} ist an. Spiele zeigen es ab jetzt.", it = "{0} è attivo. I giochi lo mostrano da ora.", es = "{0} está activada. Los juegos la muestran desde ahora.", br = "{0} está ativa. Os jogos a mostram a partir de agora.", pt = "{0} está ativa. Os jogos passam a mostrá-la.", ko = "{0} 켜짐. 이제부터 게임에 표시돼요."),
    "{0} overlays added. Tap one to use it." to Tr(ja = "オーバーレイを {0}こ ついかしました。 つかう ものを タッチして ください。", fr = "{0} surimpressions ajoutées. Touchez-en une pour l'utiliser.", de = "{0} Overlays hinzugefügt. Tippe eines an, um es zu nutzen.", it = "{0} overlay aggiunti. Toccane uno per usarlo.", es = "{0} superposiciones añadidas. Toca una para usarla.", br = "{0} molduras adicionadas. Toque em uma para usá-la.", pt = "{0} molduras adicionadas. Toque numa para a usar.", ko = "오버레이 {0}개를 추가했어요. 탭해서 사용하세요."),
    "{0} couldn't be used: an image missing, or not a PNG." to Tr(ja = "{0}こは つかえませんでした: がぞうが ないか PNGでは ありません。", fr = "{0} inutilisable(s) : image manquante ou pas un PNG.", de = "{0} nicht nutzbar: Bild fehlt oder kein PNG.", it = "{0} non utilizzabili: immagine mancante o non PNG.", es = "{0} no se pudieron usar: falta una imagen o no es PNG.", br = "{0} não puderam ser usadas: falta uma imagem ou não é PNG.", pt = "{0} não puderam ser usadas: falta uma imagem ou não é PNG.", ko = "{0}개는 쓸 수 없어요: 이미지가 없거나 PNG가 아니에요."),
